import { prisma } from "@/lib/prisma";
import AnimatedCounter from "@/components/AnimatedCounter";
import PartnerCarousel from "@/components/PartnerCarousel";
import Image from "next/image";

export const metadata = {
    title: "Бидний тухай | МҮЗХ",
    description: "Монголын Үндэсний Зуслангуудын Холбооны Танилцуулга",
};

export default async function AboutPage() {
    // 1. Fetch settings from DB
    const settingsRows = await prisma.siteSetting.findMany();
    const settings = settingsRows.reduce((acc, curr) => {
        acc[curr.key] = curr.value;
        return acc;
    }, {} as Record<string, string>);

    // 2. Fetch Board Members
    const boardMembers = await prisma.post.findMany({
        where: { type: "BOARD_MEMBER", published: true },
        orderBy: { createdAt: "asc" }
    });

    // Extract dynamic variables with fallbacks
    const heroImage = settings.about_hero_image || "https://images.unsplash.com/photo-1526779259212-939e64788e3c?q=80&w=2074&auto=format&fit=crop";
    const heroTitle = settings.about_hero_title || "БИДНИЙ ТУХАЙ";
    const heroSubtitle = settings.about_hero_subtitle || "Монголын Үндэсний Зуслангуудын Холбооны Танилцуулга";
    const missionText = settings.about_hero_title || "Монголын Үндэсний Зуслангуудын Холбоо (МҮЗХ) нь үүсгэн байгуулагч гишүүдийн санаачилгаар 2006 онд байгуулагдсан үндэсний хэмжээний төрийн бус байгууллага юм.";
    
    let timeline: any[] = [];
    try {
        const parsed = JSON.parse(settings.about_timeline || "[]");
        if (parsed && parsed.length > 0) {
            timeline = parsed;
        } else {
            timeline = [
                {year: "2006", title: "Үүсгэн байгуулагдсан", description: "Монгол улсад үйл ажиллагаа явуулж буй зуслангуудыг нэгтгэв."},
                {year: "2012", title: "ОУЗХ-ны гишүүн", description: "Олон улсын зуслангийн холбоо (ICF)-ны жинхэнэ гишүүн байгууллага болсон."},
                {year: "2025", title: "Ази, Номхон далай", description: "Ази, номхон далайн орнуудын зуслангийн холбоог үүсгэн байгууллаа."}
            ];
        }
    } catch(e) {}

    return (
        <div className="bg-slate-50 min-h-screen">
            {/* 1. Parallax Hero Section */}
            <section className="relative h-[40vh] md:h-[50vh] flex items-center justify-center overflow-hidden">
                <div 
                    className="absolute inset-0 z-0"
                    style={{
                        backgroundImage: `url('${heroImage}')`,
                        backgroundPosition: 'center',
                        backgroundSize: 'cover',
                        backgroundAttachment: 'fixed', // Parallax effect
                    }}
                >
                    <div className="absolute inset-0 bg-slate-900/60 mix-blend-multiply"></div>
                </div>
                
                <div className="relative z-10 text-center px-4 space-y-4 max-w-4xl mx-auto text-white">
                    <h1 className="text-4xl md:text-5xl lg:text-7xl font-black tracking-tight drop-shadow-md">
                        {heroTitle}
                    </h1>
                    <p className="text-lg md:text-2xl font-medium text-slate-100 drop-shadow max-w-2xl mx-auto leading-relaxed">
                        {heroSubtitle}
                    </p>
                </div>
            </section>

            {/* 2. Interactive Stats Section */}
            <section className="relative z-20 -mt-12 md:-mt-16 container mx-auto px-4">
                <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 p-6 md:p-10 border border-slate-100 grid grid-cols-2 md:grid-cols-4 gap-6 md:gap-8 divide-x divide-slate-100">
                    <div className="text-center px-4">
                        <AnimatedCounter value={settings.stat1Year || "2006"} className="text-4xl md:text-5xl font-extrabold text-blue-600 block mb-2" />
                        <span className="text-sm md:text-base font-semibold text-slate-500 uppercase tracking-wider">{settings.stat1Label || "Байгуулагдсан он"}</span>
                    </div>
                    <div className="text-center px-4">
                        <AnimatedCounter value={settings.stat2Number || "100+"} className="text-4xl md:text-5xl font-extrabold text-blue-600 block mb-2" />
                        <span className="text-sm md:text-base font-semibold text-slate-500 uppercase tracking-wider">{settings.stat2Label || "Бүртгэлтэй Зуслан"}</span>
                    </div>
                    <div className="text-center px-4">
                        <AnimatedCounter value={settings.stat3Year || "2012"} className="text-4xl md:text-5xl font-extrabold text-blue-600 block mb-2" />
                        <span className="text-sm md:text-base font-semibold text-slate-500 uppercase tracking-wider">{settings.stat3Label || "ОУЗХ-ны гишүүн"}</span>
                    </div>
                    <div className="text-center px-4">
                        <AnimatedCounter value={settings.stat4Number || "15+"} className="text-4xl md:text-5xl font-extrabold text-blue-600 block mb-2" />
                        <span className="text-sm md:text-base font-semibold text-slate-500 uppercase tracking-wider">{settings.stat4Label || "ОУ-ын түншлэл"}</span>
                    </div>
                </div>
            </section>

            {/* 3. Board Members (Moved from bottom) */}
            {boardMembers.length > 0 && (
                <section className="container mx-auto px-4 py-20 max-w-6xl">
                    <div className="text-center max-w-3xl mx-auto mb-16">
                        <h2 className="text-3xl md:text-4xl font-bold text-slate-900 mb-6">Удирдах зөвлөл</h2>
                        <p className="text-lg text-slate-600 leading-relaxed">
                            МҮЗХ-ны бодлого, стратегийн хэрэгжилтийг хангаж, салбарын хөгжлийг түүчээлэгч манлайлагчид.
                        </p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                        {boardMembers.map((member) => (
                            <div key={member.id} className="group text-center">
                                <div className="relative w-48 h-48 mx-auto mb-6 rounded-full overflow-hidden border-4 border-white shadow-xl transition-transform duration-300 group-hover:scale-105 group-hover:border-blue-100 bg-slate-200">
                                    {member.imageUrl ? (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img 
                                            src={member.imageUrl} 
                                            alt={member.title}
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-4xl font-bold text-slate-400">
                                            {member.title.charAt(0)}
                                        </div>
                                    )}
                                </div>
                                <h3 className="text-xl font-bold text-slate-900 mb-1">{member.title}</h3>
                                <p className="text-sm font-semibold text-blue-600 uppercase tracking-wide">{member.excerpt || "Удирдах зөвлөлийн гишүүн"}</p>
                            </div>
                        ))}
                    </div>
                </section>
            )}

            {/* 4. Main Mission & Values (Cards with Icons) */}
            <section className="container mx-auto px-4 py-20 max-w-6xl">
                <div className="text-center max-w-3xl mx-auto mb-16">
                    <h2 className="text-3xl md:text-4xl font-bold text-slate-900 mb-6">Бидний эрхэм зорилго</h2>
                    <p className="text-lg text-slate-600 leading-relaxed">
                        {settings.about_mission_text || missionText}
                    </p>
                </div>

                <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {/* Value Card 1 */}
                    <div className="bg-white p-8 rounded-2xl border shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 group">
                        <div className="w-14 h-14 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
                        </div>
                        <h4 className="font-bold text-xl mb-3">Хууль тогтоомж</h4>
                        <p className="text-slate-500 leading-relaxed text-sm">
                            Хүүхдийн хөгжил, хамгаалал, оролцооны чиглэлээрх хууль тогтоомж, бодлогын хэрэгжилтийг хангах, салбарын эрх зүйн орчныг боловсронгуй болгох.
                        </p>
                    </div>

                    {/* Value Card 2 */}
                    <div className="bg-white p-8 rounded-2xl border shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 group">
                        <div className="w-14 h-14 bg-green-50 text-green-600 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z" /></svg>
                        </div>
                        <h4 className="font-bold text-xl mb-3">Хөтөлбөрийн чанар</h4>
                        <p className="text-slate-500 leading-relaxed text-sm">
                            Нас, хөгжлийн онцлогт тохирсон ялгаатай, уян хатан хөгжлийн хөтөлбөрийг шинэчлэн боловсруулах, үнэлгээ дүгнэлт хийх.
                        </p>
                    </div>

                    {/* Value Card 3 */}
                    <div className="bg-white p-8 rounded-2xl border shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 group">
                        <div className="w-14 h-14 bg-purple-50 text-purple-600 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                        </div>
                        <h4 className="font-bold text-xl mb-3">Судалгаа</h4>
                        <p className="text-slate-500 leading-relaxed text-sm">
                            Олон улсын хамтын ажиллагааг өргөжүүлэх, төсөл, хөтөлбөрт хамрагдах, шинжлэх ухааны суурь болон хэрэглээний судалгаа хийх.
                        </p>
                    </div>

                    {/* Value Card 4 */}
                    <div className="bg-white p-8 rounded-2xl border shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 group">
                        <div className="w-14 h-14 bg-orange-50 text-orange-600 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                            <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
                        </div>
                        <h4 className="font-bold text-xl mb-3">Хүний нөөц</h4>
                        <p className="text-slate-500 leading-relaxed text-sm">
                            Салбарын хүний нөөцийн сургалт, мэргэжлийн хөгжлийг дэмжих, зуслангийн багш, нийгмийн ажилтнуудыг бэлтгэх.
                        </p>
                    </div>
                </div>
            </section>

            {/* 5. Interactive Timeline */}
            {timeline.length > 0 && (
                <section className="bg-slate-900 text-white py-24 relative overflow-hidden">
                    <div className="absolute top-0 right-0 -mt-20 -mr-20 w-80 h-80 bg-blue-600 rounded-full blur-[120px] opacity-20 hidden md:block"></div>
                    <div className="absolute bottom-0 left-0 -mb-20 -ml-20 w-80 h-80 bg-purple-600 rounded-full blur-[120px] opacity-20 hidden md:block"></div>
                    
                    <div className="container mx-auto px-4 max-w-5xl relative z-10">
                        <h2 className="text-3xl md:text-4xl font-bold mb-16 text-center">Хөгжил, Хүрсэн Үр Дүн</h2>
                        
                        <div className="relative border-l-2 border-slate-700 ml-4 md:ml-0 md:border-l-0">
                            {/* Desktop Line */}
                            <div className="hidden md:block absolute left-1/2 top-0 bottom-0 w-0.5 bg-slate-700 transform -translate-x-1/2"></div>
                            
                            <div className="space-y-12">
                                {timeline.map((event, i) => (
                                    <div key={i} className={`relative flex flex-col md:flex-row items-center ${i % 2 === 0 ? 'md:justify-start' : 'md:justify-end'}`}>
                                        
                                        {/* Mobile Circle */}
                                        <div className="absolute left-[-21px] md:hidden w-4 h-4 rounded-full bg-blue-500 border-4 border-slate-900"></div>

                                        <div className={`w-full md:w-[45%] lg:w-[40%] ml-6 md:ml-0 p-6 rounded-2xl bg-slate-800 border border-slate-700 hover:border-blue-500 transition-colors group`}>
                                            <span className="text-blue-400 font-bold text-xl mb-2 block">{event.year}</span>
                                            <h4 className="text-xl font-bold mb-3 text-white group-hover:text-blue-400 transition-colors">{event.title}</h4>
                                            <p className="text-slate-400 leading-relaxed text-sm">{event.description}</p>
                                        </div>

                                        {/* Desktop Circle */}
                                        <div className="hidden md:flex absolute left-1/2 transform -translate-x-1/2 items-center justify-center w-8 h-8 rounded-full bg-slate-900 border-4 border-slate-700 z-10">
                                            <div className="w-2.5 h-2.5 rounded-full bg-blue-500"></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </section>
            )}

            {/* 6. Partner Carousel */}
            <section className="bg-white py-16 border-t border-slate-100">
                <PartnerCarousel />
            </section>
        </div>
    );
}
